import heapq

def match(orders):
    buy_heap = []  # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    book = {}  # id -> dict(side, price, qty, arrival, active)
    trades = []
    counter = 0

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active'] and book[oid]['qty'] > 0:
                book[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        arrival = counter
        counter += 1
        remaining = qty

        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            if side == 'buy':
                opp_price = top[0]
            else:
                opp_price = -top[0]
            opp_id = top[2]

            if opp_id not in book or not book[opp_id]['active'] or book[opp_id]['qty'] <= 0:
                heapq.heappop(opp_heap)
                continue

            if price is not None:
                if side == 'buy' and opp_price > price:
                    break
                if side == 'sell' and opp_price < price:
                    break

            trade_qty = min(remaining, book[opp_id]['qty'])
            trade_price = opp_price

            if side == 'buy':
                trades.append([oid, opp_id, trade_price, trade_qty])
            else:
                trades.append([opp_id, oid, trade_price, trade_qty])

            remaining -= trade_qty
            book[opp_id]['qty'] -= trade_qty

            if book[opp_id]['qty'] == 0:
                book[opp_id]['active'] = False
                heapq.heappop(opp_heap)

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'arrival': arrival, 'active': True}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, arrival, oid))
            else:
                heapq.heappush(sell_heap, (price, arrival, oid))
        # ioc/market: remainder discarded, nothing to do

    return trades

